INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('arms', 'warmup', 'Arm circles', 'Shoulders', 30, '{"kind":"flow","phases":[{"l":"Circle forward","d":5},{"l":"Circle back","d":5,"ease":true}]}', '["Stand tall, arms straight out to the sides at shoulder height.","Draw slow circles about the size of a dinner plate — 15 forward, then reverse.","Keep your shoulders down, away from your ears."]', NULL, 'Warms the shoulders for push-ups.', 'none', 0);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('swings', 'warmup', 'Leg swings', 'Hips', 30, '{"kind":"flow","phases":[{"l":"Swing forward","d":1},{"l":"Swing back","d":1,"ease":true}]}', '["Hold a wall or doorframe for balance.","Swing one leg forward and back like a relaxed pendulum, letting the hip open.","Keep your torso upright and core lightly braced. Switch legs at the halfway point."]', NULL, 'Loosens hips and hamstrings before squats and lunges.', 'none', 1);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('hipc', 'warmup', 'Hip circles', 'Hips', 30, '{"kind":"flow","phases":[{"l":"Circle one way","d":6},{"l":"Circle the other","d":6,"ease":true}]}', '["Hands on hips, feet shoulder-width apart.","Draw big slow circles with your beltline, like working a hula hoop.","Half the time one direction, half the other."]', NULL, 'Opens the hips and lower back.', 'none', 2);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('catcow', 'warmup', 'Cat-cow', 'Spine', 30, '{"kind":"hold","phases":[{"l":"Inhale, drop & open","d":3},{"l":"Exhale, round up","d":3,"ease":true}]}', '["On hands and knees, wrists under shoulders, knees under hips.","Inhale: drop your belly, lift your chest and tailbone (cow).","Exhale: round your spine to the ceiling, tuck your chin and tail (cat).","Move with your breath, slow and smooth."]', NULL, 'Wakes up the spine — good if you sit a lot.', 'none', 3);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('wsquat', 'warmup', 'Slow squats', 'Legs', 35, '{"kind":"reps","phases":[{"l":"Lower slowly","d":3},{"l":"Stand tall","d":2,"ease":true}]}', '["Feet shoulder-width, toes turned slightly out.","Sink down slowly over three counts, as deep as is comfortable.","Stand back up over two counts. No load yet — this just greases the knees and hips."]', NULL, 'Stay flat-footed and quiet; no bouncing at the bottom.', 'none', 4);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('squat', 'circuit', 'Squats', 'Legs', 40, '{"kind":"reps","phases":[{"l":"Lower","d":2},{"l":"Drive up","d":1,"ease":true}]}', '["Stand feet shoulder-width, toes slightly out, core braced.","Push your hips back and bend your knees, lowering until your thighs are about parallel to the floor.","Keep your weight in your heels and chest up; let your knees track out over your toes.","Drive through the whole foot to stand tall, squeezing your glutes at the top."]', 'Knees caving inward or heels lifting — push the knees out and sit back into the heels.', 'Stay flat-footed; control the descent so there''s no thud.', 'none', 0);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('pushup', 'circuit', 'Push-ups', 'Chest · arms', 30, '{"kind":"reps","phases":[{"l":"Lower","d":2},{"l":"Press up","d":1,"ease":true}]}', '["Hands slightly wider than your shoulders, body in one straight line from head to heels.","Lower your chest toward the floor, elbows angled about 45° from your body — not flared straight out.","Press back up, keeping your core and glutes tight so your hips don''t sag.","Scale it: drop to your knees, or put your hands on the bed for an incline."]', 'Hips sagging or sticking up — brace your core and squeeze your glutes to hold the plank line.', 'Lower with control; no flopping to the floor.', 'none', 1);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('lunge', 'circuit', 'Reverse lunges', 'Legs', 40, '{"kind":"alt","per":"side","phases":[{"l":"Step back & lower","d":2},{"l":"Drive up","d":1,"ease":true}]}', '["Stand tall, hands on your hips or by your sides.","Step one foot straight back and lower until both knees bend to about 90°, front shin vertical.","Push through your front heel to return to standing.","Alternate legs each rep. Stepping back rather than forward is gentler on the knees and quieter."]', 'Front knee drifting past the toes — keep the front shin vertical and the weight in that heel.', 'Place the back foot down softly rather than tapping it.', 'none', 2);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('plank', 'circuit', 'Plank', 'Core', 30, '{"kind":"hold","phases":[{"l":"Breathe in","d":4},{"l":"Breathe out","d":4,"ease":true}]}', '["Forearms on the floor, elbows directly under your shoulders, toes tucked under.","Form one straight line from your head to your heels.","Squeeze your glutes and brace your abs as if bracing to be poked.","Breathe steadily — don''t hold your breath."]', 'Hips piking up or sagging down — hold a flat line from shoulders to heels.', 'Fully silent — a perfect third-floor move.', 'none', 3);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('bridge', 'circuit', 'Glute bridges', 'Glutes', 30, '{"kind":"reps","phases":[{"l":"Drive hips up","d":1},{"l":"Squeeze","d":1},{"l":"Lower slowly","d":2,"ease":true}]}', '["Lie on your back, knees bent, feet flat and hip-width, arms by your sides.","Press through your heels and lift your hips until knees, hips and shoulders form a straight line.","Squeeze your glutes hard at the top and pause.","Lower slowly with control — don''t just drop."]', 'Arching the lower back instead of using the glutes — keep ribs down and squeeze the glutes to lift.', 'Silent and floor-based.', 'none', 4);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('taps', 'circuit', 'Shoulder taps', 'Core · full body', 30, '{"kind":"alt","per":"tap","phases":[{"l":"Tap shoulder","d":1},{"l":"Other hand","d":1,"ease":true}]}', '["Start in a high plank (hands under shoulders), feet a little wider than usual for stability.","Without letting your hips rock side to side, lift one hand and tap the opposite shoulder.","Return it and switch hands. Slow and steady beats fast.","This is the quiet stand-in for mountain climbers — same core and shoulder work, no jumping."]', 'Hips swaying with each tap — widen your feet and brace hard to keep them still.', 'No impact at all — the whole point of the swap.', 'none', 5);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('wallsit', 'circuit', 'Wall sit', 'Legs', 35, '{"kind":"hold","phases":[{"l":"Breathe in","d":4},{"l":"Breathe out","d":4,"ease":true}]}', '["Stand with your back flat against a wall.","Slide down until your thighs are parallel to the floor and your knees are stacked over your ankles.","Hold the position, weight in your heels, back flat on the wall.","Breathe steadily through the burn."]', 'Knees pushing past the toes — walk your feet out until the shins are vertical.', 'Completely silent.', 'none', 6);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('deadbug', 'circuit', 'Dead bugs', 'Core', 35, '{"kind":"alt","per":"side","phases":[{"l":"Extend & lower","d":2},{"l":"Return","d":1,"ease":true}]}', '["Lie on your back, arms reaching straight up, knees bent 90° stacked over your hips.","Slowly lower your opposite arm and leg toward the floor while pressing your lower back flat into the ground.","Return to the start and switch sides.","Move slowly — control is the whole exercise."]', 'Lower back arching off the floor — only reach as far as you can while keeping it pressed flat.', 'Floor-based and silent.', 'none', 7);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('birddog', 'circuit', 'Bird dogs', 'Core · back', 35, '{"kind":"alt","per":"side","phases":[{"l":"Extend out","d":2},{"l":"Hold","d":1},{"l":"Return","d":1,"ease":true}]}', '["On hands and knees, wrists under shoulders, knees under hips.","Reach your opposite arm and leg straight out until they''re level with your body.","Pause, keeping your hips square to the floor and core braced, then return with control.","Switch sides each rep."]', 'Hips twisting toward the lifted leg — keep them level, as if balancing a glass on your back.', 'Silent and controlled.', 'none', 8);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('calf', 'circuit', 'Calf raises', 'Legs', 30, '{"kind":"reps","phases":[{"l":"Rise up","d":1},{"l":"Pause","d":1},{"l":"Lower slowly","d":2,"ease":true}]}', '["Stand tall, feet hip-width — hold a wall for balance if you like.","Rise up onto the balls of your feet as high as you can.","Pause at the top, then lower your heels slowly back down.","Barefoot is ideal here for ankle and foot strength."]', 'Bouncing through the reps — pause at the top and control the way down.', 'Lower softly so your heels don''t tap the floor.', 'none', 9);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('dips', 'circuit', 'Tricep dips', 'Arms', 30, '{"kind":"reps","phases":[{"l":"Lower","d":2},{"l":"Press up","d":1,"ease":true}]}', '["Sit on the edge of a sturdy bed or chair, hands gripping the edge beside your hips, fingers pointing forward.","Slide your hips off the edge, legs out in front.","Bend your elbows straight back to lower your hips, then press back up.","Keep your elbows tracking backward, not flaring out to the sides."]', 'Shrugging your shoulders up to your ears — keep them down and drive from the triceps.', 'Use a solid, non-creaky surface; move smoothly.', 'none', 10);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('sideplank', 'circuit', 'Side plank', 'Core', 30, '{"kind":"hold","phases":[{"l":"Breathe in","d":4},{"l":"Breathe out","d":4,"ease":true}]}', '["Lie on one side, forearm down with elbow under your shoulder.","Stack your feet and lift your hips so your body is one straight line.","Hold, breathing steadily; reach your top arm to the ceiling if you like.","Switch sides at the halfway point."]', 'Hips sinking toward the floor — lift them and hold the straight line.', 'Silent.', 'none', 11);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('quad', 'cooldown', 'Quad stretch', 'Thighs', 30, '{"kind":"hold","phases":[{"l":"Hold & breathe","d":8}]}', '["Stand tall, holding a wall for balance.","Pull one heel toward your glute, keeping your knees together and hips pushed slightly forward.","Feel the stretch down the front of your thigh. Switch legs at the halfway point."]', NULL, 'Don''t yank — ease in and let it soften.', 'none', 0);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('ham', 'cooldown', 'Hamstring stretch', 'Legs', 35, '{"kind":"hold","phases":[{"l":"Hold & breathe","d":8}]}', '["Hinge forward from your hips with soft (not locked) knees and let your upper body hang.","Relax your neck and let your head be heavy.","Breathe into the stretch and let gravity do the work."]', NULL, 'Soft knees protect your lower back.', 'none', 1);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('fig4', 'cooldown', 'Figure-4 glute stretch', 'Hips', 35, '{"kind":"hold","phases":[{"l":"Hold & breathe","d":8}]}', '["Lie on your back. Cross one ankle over the opposite thigh, just above the knee.","Reach through and pull that thigh toward your chest.","Feel the stretch deep in the glute and hip. Switch sides at the halfway point."]', NULL, 'Great after squats and lunges.', 'none', 2);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('chest', 'cooldown', 'Chest opener', 'Chest', 30, '{"kind":"hold","phases":[{"l":"Hold & breathe","d":8}]}', '["Clasp your hands behind your back and gently lift them, opening across your collarbones.","Or rest a forearm on a doorframe and turn away from it.","Lift through your chest and breathe."]', NULL, 'Counteracts the push-ups and hunched desk posture.', 'none', 3);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('child', 'cooldown', 'Child''s pose', 'Back', 35, '{"kind":"hold","phases":[{"l":"Breathe in","d":5},{"l":"Breathe out","d":5,"ease":true}]}', '["Kneel with big toes together and knees wide.","Sit back onto your heels and walk your hands forward, lowering your forehead toward the floor.","Let your chest melt down and breathe slowly into your back."]', NULL, 'A calm finish to settle the breathing.', 'none', 4);
INSERT INTO exercises (id, phase, name, tag, base_dur, tempo_json, how_json, mistake, quiet, equipment, sort_order) VALUES ('twist', 'cooldown', 'Seated twist', 'Spine', 30, '{"kind":"hold","phases":[{"l":"Hold & breathe","d":8}]}', '["Sit tall with one leg crossed over the other.","Rotate gently toward the top leg, using your opposite elbow against the knee as a gentle lever.","Keep your spine long. Switch sides at the halfway point."]', NULL, 'Gentle — rotate only as far as is comfortable.', 'none', 5);
